Note that this is me reopening the following issue which was incorrectly marked as a dupe and closed+locked:
https://github.com/flutter/flutter/issues/65384

### Steps to reproduce

1. Create a navigator containing two pages (Material or Cupertino)
2. In the topmost page, return a nested navigator that itself contains two cupertino pages
3. Use the iOS backswipe gesture

### Expected results

The top page of the nested navigator is dismissed. The nested navigator remains in the tree.

### Actual results

The top page of the outer navigator is dismissed. The nested navigator is removed from the tree.

Note that programmatic calls to pop and the app bar back button both produce the expected behavior, only the iOS backswipe gesture is unexpected.

### Code sample

<details open><summary>Code sample</summary>

```dart
class NestedNavDemo extends StatefulWidget {
  const NestedNavDemo({super.key});

  @override
  State<NestedNavDemo> createState() => _NestedNavDemoState();
}

class _NestedNavDemoState extends State<NestedNavDemo> {
  bool showNestedNav = true;

  @override
  Widget build(BuildContext context) {
    return Navigator(
      onDidRemovePage: (_) => setState(() => showNestedNav = false),
      pages: [
        MaterialPage(
          child: Scaffold(
            body: InkWell(
              onTap: () => setState(() => showNestedNav = true),
              child: const Center(child: Text('Oops, popped to far. Tap to start over.')),
            ),
          ),
        ),
        if (showNestedNav) const MaterialPage(child: InnerNavigator()),
      ],
    );
  }
}

class InnerNavigator extends StatefulWidget {
  const InnerNavigator({super.key});

  @override
  State<InnerNavigator> createState() => _InnerNavigatorState();
}

class _InnerNavigatorState extends State<InnerNavigator> {
  bool showSecondColor = true;

  @override
  Widget build(BuildContext context) {
    const color = Colors.blue;
    const secondColor = Colors.red;

    return Navigator(
      onDidRemovePage: (_) => setState(() => showSecondColor = false),
      pages: [
        CupertinoPage(
          child: AppScaffold(
            appBar: AppBar(),
            body: InkWell(onTap: () => setState(() => showSecondColor = true), child: Container(color: color)),
          ),
        ),
        // Backswiping on this page will dismiss the inner navigator entirely (unexpected).
        if (showSecondColor) CupertinoPage(
          // Tapping the back button in the app bar will only dismiss the second color page (expected).
          child: Scaffold(appBar: AppBar(), body: Container(color: secondColor))
        ),
      ],
    );
  }
}
```

</details>


